import React,{useEffect,useState} from 'react';import {createRoot} from 'react-dom/client';import {ProductionReadBoundary} from '../../components/production-management';import {createProductionWorkspaceReader} from '../../lib/production-workspace-reader.mjs';import {Dialog,DialogContent,DialogTitle} from '../../components/ui/dialog';
function App(){const [reader]=useState(()=>createProductionWorkspaceReader({initial:{label:'Bảng ban đầu'},read:async()=>{await new Promise(r=>setTimeout(r,250));return {label:'Bảng cập nhật'};}}));const [s,setS]=useState(reader.getState),[open,setOpen]=useState(false);useEffect(()=>reader.subscribe(setS),[reader]);useEffect(()=>{void reader.setActive(true);},[reader]);return <main style={{padding:20}}><button onClick={()=>{void reader.setHeld(true);setOpen(true);}}>Mở báo công mẫu</button><ProductionReadBoundary hasData={!!s.value} loading={s.loading} error={s.error} retry={()=>void reader.refresh()}><table id="board" style={{width:600,border:'1px solid'}}><tbody><tr><td>{s.value?.label}</td></tr><tr><td>B PHAO · 1.000 còn lại</td></tr></tbody></table></ProductionReadBoundary><Dialog open={open} onOpenChange={v=>{setOpen(v);void reader.setHeld(v);}}><DialogContent><DialogTitle>Báo công mẫu · dữ liệu giả</DialogTitle><input aria-label="Số lượng mẫu" defaultValue="1000"/><button onClick={()=>{void reader.refresh(true);void reader.refresh(true);}}>Mô phỏng 2 cập nhật nền</button><button onClick={()=>{setOpen(false);void reader.setHeld(false);}}>Đóng mẫu</button></DialogContent></Dialog></main>};createRoot(document.getElementById('root')!).render(<App/>);
